"""Symbolic input/output layout compilation and recovery.

The counter convention mirrors the toolkit's MainBuilder: every scalar and
every composite reserves an xN identifier.  Composite identifiers and string
buffers are numbering bookkeeping, not KTEST objects; only scalar leaves and
string characters appear in ``slots``.
"""

from .model import (AliasType, ArrayType, BoolType, CharType, EnumType,
                    IntType, StringType, StructType, VoidType,
                    int_width, underlying)


class LeafSpec:
    __slots__ = ("name", "path", "width", "kind", "bits", "enum_values")

    def __init__(self, name, path, width, kind, bits=None, enum_values=None):
        self.name = name
        self.path = path
        self.width = width
        self.kind = kind
        self.bits = bits
        self.enum_values = enum_values

    def accepts(self, value):
        if self.kind == "bool" or self.kind == "flag":
            return value == 0 or value == 1
        if self.kind == "char":
            return 0 <= value <= 255
        if self.kind == "int":
            return 0 <= value < (1 << self.bits)
        if self.kind == "enum":
            return 0 <= value < len(self.enum_values)
        return False


class ValueNode:
    __slots__ = ("kind", "identifier", "width", "bits", "enum_values",
                 "children", "fields", "size", "maxsize")

    def __init__(self, kind, identifier=None, width=None, bits=None,
                 enum_values=None, children=None, fields=None, size=None,
                 maxsize=None):
        self.kind = kind
        self.identifier = identifier
        self.width = width
        self.bits = bits
        self.enum_values = enum_values
        self.children = children
        self.fields = fields
        self.size = size
        self.maxsize = maxsize

    def read(self, values):
        kind = self.kind
        if kind == "void":
            return None
        if kind == "bool":
            return bool(values[self.identifier])
        if kind == "char":
            return chr(values[self.identifier])
        if kind == "int":
            return values[self.identifier]
        if kind == "enum":
            return self.enum_values[values[self.identifier]]
        if kind == "string":
            raw = [values[child.identifier] for child in self.children]
            result = []
            for code in raw:
                if code == 0:
                    break
                result.append(chr(code))
            return "".join(result)
        if kind == "array":
            return [child.read(values) for child in self.children]
        if kind == "struct":
            return {field_name: child.read(values)
                    for field_name, child in self.fields}
        raise ValueError("invalid layout node")


class PlanLayout:
    __slots__ = ("roots", "result", "slots", "flag", "variables", "expected")

    def __init__(self, roots, result, slots, flag, variables, expected):
        self.roots = roots
        self.result = result
        self.slots = slots
        self.flag = flag
        self.variables = variables
        self.expected = expected

    def recover_inputs(self, values):
        return [(name, node.read(values)) for name, node in self.roots]

    def recover_result(self, values):
        return self.result.read(values)


class LayoutBuilder:
    __slots__ = ("number", "slots", "expected")

    def __init__(self):
        self.number = 0
        self.slots = []
        self.expected = {}

    def reserve(self):
        number = self.number
        self.number += 1
        return number

    def _scalar(self, kind, path, width, bits=None, enum_values=None):
        identifier = self.reserve()
        name = "x" + str(identifier)
        self.slots.append([name, list(path), width])
        self.expected[name.encode("ascii")] = LeafSpec(
            name, list(path), width, kind, bits=bits,
            enum_values=enum_values)
        return ValueNode(kind, identifier=name.encode("ascii"),
                         width=width, bits=bits, enum_values=enum_values)

    def _string_char(self, path):
        identifier = self.reserve()
        name = "x" + str(identifier)
        self.slots.append([name, list(path), 1])
        self.expected[name.encode("ascii")] = LeafSpec(
            name, list(path), 1, "char")
        return ValueNode("char", identifier=name.encode("ascii"), width=1)

    def build(self, type_node, path):
        while isinstance(type_node, AliasType):
            type_node = type_node.target
        if isinstance(type_node, VoidType):
            return ValueNode("void")
        if isinstance(type_node, BoolType):
            return self._scalar("bool", path, 1)
        if isinstance(type_node, CharType):
            return self._scalar("char", path, 1)
        if isinstance(type_node, IntType):
            return self._scalar("int", path, int_width(type_node.bits),
                                bits=type_node.bits)
        if isinstance(type_node, EnumType):
            return self._scalar("enum", path, 4,
                                enum_values=type_node.values)
        if isinstance(type_node, StringType):
            buffer_id = self.reserve()
            children = [self._string_char(path + [index])
                        for index in range(type_node.maxsize)]
            return ValueNode("string", identifier=buffer_id,
                             children=children, maxsize=type_node.maxsize)
        if isinstance(type_node, ArrayType):
            identifier = self.reserve()
            children = [self.build(type_node.element, path + [index])
                        for index in range(type_node.size)]
            return ValueNode("array", identifier=identifier,
                             children=children, size=type_node.size)
        if isinstance(type_node, StructType):
            identifier = self.reserve()
            fields = [(field_name,
                       self.build(field_type, path + [field_name]))
                      for field_name, field_type in type_node.fields]
            return ValueNode("struct", identifier=identifier, fields=fields)
        raise ValueError("invalid type in layout")


def compile_layout(module, direct_pipe):
    builder = LayoutBuilder()
    roots = []
    for parameter_name, parameter_type in module.params:
        roots.append((parameter_name,
                      builder.build(parameter_type, [parameter_name])))
    result = builder.build(module.result_type, [module.result_name])
    flag = None
    if direct_pipe:
        flag_id = builder.reserve()
        flag = "x" + str(flag_id)
        builder.expected[flag.encode("ascii")] = LeafSpec(
            flag, None, 1, "flag")
    return PlanLayout(roots, result, builder.slots, flag, builder.number,
                      builder.expected)
