"""Strict binary symbolic-test transport (KTEST v3).

Only leaf objects are expected.  Composite identifiers reserve xN numbers in a
plan, but carrying one in a KTEST is an inventory error.
"""

import base64
import binascii
import re

_BASE64 = re.compile(
    r"(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?\Z")


class WireError(ValueError):
    pass


class _Reader:
    __slots__ = ("data", "position", "length")

    def __init__(self, data):
        self.data = data
        self.position = 0
        self.length = len(data)

    def take(self, count):
        if count < 0:
            raise WireError("negative length")
        end = self.position + count
        if end > self.length:
            raise WireError("truncated payload")
        value = self.data[self.position:end]
        self.position = end
        return value

    def u32(self):
        return int.from_bytes(self.take(4), "big", signed=False)

    def blob(self, maximum=None):
        size = self.u32()
        if maximum is not None and size > maximum:
            raise WireError("blob too large")
        return self.take(size)

    def at_end(self):
        return self.position == self.length


def _decode_base64(value):
    if not isinstance(value, str) or _BASE64.fullmatch(value) is None:
        raise WireError("invalid base64")
    try:
        encoded = value.encode("ascii")
        return base64.b64decode(encoded, validate=True)
    except (UnicodeError, binascii.Error, ValueError) as exc:
        raise WireError("invalid base64") from exc


def _canonical_name(name):
    # A canonical object name is ASCII 'x' followed by a nonnegative decimal
    # integer with no leading zeros.
    if len(name) < 2 or name[0] != 0x78:
        return False
    digits = name[1:]
    if not digits:
        return False
    if len(digits) > 1 and digits[0] == 0x30:
        return False
    for byte in digits:
        if byte < 0x30 or byte > 0x39:
            return False
    return True


def decode(payload, expected):
    """Decode a base64 KTEST and validate it against ``expected``.

    ``expected`` maps ASCII object-name bytes to LeafSpec-like objects with
    ``width`` and ``accepts(int)``.  Returns a mapping from object-name bytes
    to little-endian leaf integers.  Any transport, inventory or leaf-range
    problem raises :class:`WireError`.
    """
    data = _decode_base64(payload)
    reader = _Reader(data)
    if reader.take(5) != b"KTEST":
        raise WireError("bad magic")
    if reader.u32() != 3:
        raise WireError("bad version")

    argument_count = reader.u32()
    if argument_count > 64:
        raise WireError("too many arguments")
    for _ in range(argument_count):
        reader.blob(maximum=256)

    # Both symbolic-argv bookkeeping words are opaque and ignored.
    reader.u32()
    reader.u32()

    object_count = reader.u32()
    # Inventory cardinality is known from the compiled plan.  This also makes
    # arbitrarily large declared counts cheap to reject.
    if object_count != len(expected):
        raise WireError("wrong object count")

    values = {}
    seen = set()
    for _ in range(object_count):
        name = reader.blob()
        blob = reader.blob()
        if name in seen:
            raise WireError("duplicate object")
        seen.add(name)
        if not _canonical_name(name):
            raise WireError("noncanonical object name")
        spec = expected.get(name)
        if spec is None:
            raise WireError("unknown object")
        if len(blob) != spec.width:
            raise WireError("wrong object width")
        value = int.from_bytes(blob, "little", signed=False)
        if not spec.accepts(value):
            raise WireError("leaf out of range")
        values[name] = value

    if not reader.at_end():
        raise WireError("trailing bytes")
    if len(values) != len(expected):
        raise WireError("missing object")
    return values
